select jsonb_pretty(jsonb_build_object(
 'now', now(),
 'session_user', session_user, 'current_user', current_user,
 'server_version', current_setting('server_version'),
 'db_collation', (select datcollate from pg_database where datname = current_database()),
 'help_table_exists', to_regclass('mazer.mazer_help_requests') is not null,
 'help_fn_exists', to_regprocedure('mazer.mazer_submit_help_request_v1(text, text, text, integer, text)') is not null,
 'help_fn_by_name_any_schema', (select jsonb_agg(p.oid::regprocedure::text order by 1) from pg_proc p where p.proname ilike '%help%'),
 'help_like_relations_any_schema', (select jsonb_agg(n.nspname||'.'||c.relname order by 1) from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relname ilike '%help%'),
 'support_like_relations_any_schema', (select jsonb_agg(n.nspname||'.'||c.relname order by 1) from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relname ilike '%support%'),
 'mazer_schema_owner', (select pg_get_userbyid(nspowner) from pg_namespace where nspname = 'mazer'),
 'mazer_schema_acl', (select nspacl::text from pg_namespace where nspname = 'mazer'),
 'mazer_relations', (select jsonb_agg(c.relname || ' owner=' || pg_get_userbyid(c.relowner) || ' rls=' || c.relrowsecurity::text || ' acl=' || coalesce(c.relacl::text, 'null') order by c.relname) from pg_class c where c.relnamespace = 'mazer'::regnamespace and c.relkind in ('r','v','p')),
 'mazer_functions_acl', (select jsonb_agg(p.oid::regprocedure::text || ' owner=' || pg_get_userbyid(p.proowner) || ' definer=' || p.prosecdef::text || ' acl=' || coalesce(p.proacl::text, 'null') order by 1) from pg_proc p where p.pronamespace = 'mazer'::regnamespace),
 'mazer_functions_anon_can_execute', (select jsonb_agg(p.oid::regprocedure::text order by 1) from pg_proc p where p.pronamespace = 'mazer'::regnamespace and has_function_privilege('anon', p.oid, 'EXECUTE')),
 'default_acls_mazer', (select jsonb_agg(defaclrole::regrole::text||' '||defaclobjtype::text||' '||defaclacl::text) from pg_default_acl where defaclnamespace='mazer'::regnamespace),
 'roles_present', (select jsonb_object_agg(r, exists (select 1 from pg_roles where rolname = r)) from unnest(array['anon','authenticated','service_role','authenticator','supabase_auth_admin']) r),
 'service_role_bypassrls', (select rolbypassrls from pg_roles where rolname='service_role'),
 'authenticator_rolconfig', (select rolconfig::text from pg_roles where rolname = 'authenticator'),
 'references_on_auth_users', jsonb_build_object(
    'postgres', has_table_privilege('postgres','auth.users','REFERENCES'),
    'current_user', has_table_privilege(current_user,'auth.users','REFERENCES')),
 'auth_users_owner', (select pg_get_userbyid(relowner) from pg_class where oid='auth.users'::regclass),
 'existing_mazer_fk_to_auth_users', (select jsonb_agg(conrelid::regclass::text||' '||confdeltype::text order by 1) from pg_constraint where contype='f' and confrelid='auth.users'::regclass and connamespace='mazer'::regnamespace),
 'feedback_v2_installed', jsonb_build_object(
    'table', to_regclass('mazer.mazer_feedback') is not null,
    'fn', to_regprocedure('mazer.mazer_submit_feedback_v1(integer, text, text, integer, text, text)') is not null,
    'rows_total', (select count(*) from mazer.mazer_feedback)),
 'delete_account_v2', jsonb_build_object(
    'inner_exists', to_regprocedure('account_private.delete_account_v2(uuid, jsonb, text)') is not null,
    'inner_md5', (select md5(prosrc) from pg_proc where oid = to_regprocedure('account_private.delete_account_v2(uuid, jsonb, text)')),
    'inner_mentions_help', (select prosrc ilike '%help%' from pg_proc where oid = to_regprocedure('account_private.delete_account_v2(uuid, jsonb, text)')),
    'inner_mentions_feedback', (select prosrc ilike '%mazer_feedback%' from pg_proc where oid = to_regprocedure('account_private.delete_account_v2(uuid, jsonb, text)'))),
 'logging_settings', (select jsonb_object_agg(name, setting) from pg_settings where name in ('log_statement', 'log_min_error_statement', 'log_min_duration_statement', 'log_parameter_max_length', 'log_parameter_max_length_on_error', 'log_min_messages')),
 'open_transactions', (select jsonb_agg(jsonb_build_object('pid', pid, 'state', state, 'xact_age_s', extract(epoch from now()-xact_start)::int, 'app', application_name)) from pg_stat_activity where xact_start is not null and pid <> pg_backend_pid() and state <> 'idle' and backend_type = 'client backend'),
 'ungranted_waits_on_auth_users', (select count(*) from pg_locks where relation = 'auth.users'::regclass and not granted),
 'auth_users_total', (select count(*) from auth.users),
 'auth_users_created_24h', (select count(*) from auth.users where created_at > now() - interval '24 hours'),
 'auth_users_anonymous', (select count(*) from auth.users where is_anonymous)
)) as preimage;
